CREATE TYPE compliance_estado AS ENUM\n  ('PENDIENTE','VERIFICADO','RECHAZADO','REVOCADO','EXPIRADO');\nCREATE TYPE compliance_estado_global AS ENUM\n  ('VIGENTE','BLOQUEADO','PARCIAL','SIN_DATOS');\n\nCREATE TABLE compliance_subcontractor_head (\n  tenant_id                     uuid NOT NULL,\n  subcontractor_id              uuid NOT NULL,\n  project_id                    uuid NOT NULL,\n  estado_global                 compliance_estado_global NOT NULL,\n  version_actual                bigint NOT NULL,\n  requisito_critico_id          uuid NOT NULL,\n  requisito_critico_tipo        varchar(40) NOT NULL,\n  requisito_critico_estado      compliance_estado NOT NULL,\n  requisito_critico_vencimiento date NOT NULL,\n  requisitos_total              int NOT NULL,\n  requisitos_vigentes           int NOT NULL,\n  requisitos_bloqueados         int NOT NULL,\n  ultimo_evento_id              uuid NOT NULL,\n  actualizado_en                timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, subcontractor_id, project_id)\n);\n\nCREATE TABLE compliance_requirement (\n  tenant_id            uuid NOT NULL,\n  requisito_id         uuid NOT NULL,\n  subcontractor_id     uuid NOT NULL,\n  project_id           uuid NOT NULL,\n  tipo_requisito       varchar(40) NOT NULL,\n  estado_verificacion  compliance_estado NOT NULL DEFAULT 'PENDIENTE',\n  fecha_vencimiento    date NOT NULL,\n  documento_id         uuid,\n  aseguradora_o_emisor varchar(200),\n  fuente_evento_id     uuid NOT NULL,\n  version_fila         bigint NOT NULL,\n  actualizado_en       timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, requisito_id)\n);\nCREATE INDEX idx_cr_lookup ON compliance_requirement\n  (tenant_id, subcontractor_id, project_id);\n\nALTER TABLE compliance_subcontractor_head ENABLE ROW LEVEL SECURITY;\nALTER TABLE compliance_requirement         ENABLE ROW LEVEL SECURITY;\nCREATE POLICY ti_csh ON compliance_subcontractor_head\n  USING (tenant_id = current_setting('app.tenant_id')::uuid);\nCREATE POLICY ti_cr ON compliance_requirement\n  USING (tenant_id = current_setting('app.tenant_id')::uuid);